  'streamingConsentNotice.acceptance': '続行すると、この機能は個人用ローカルクライアントの補助入口であり、法律助言、著作権許諾、プラットフォーム代理関係、またはコンテンツ利用可能性の保証ではないことを理解し同意したものとみなします。',
  'streamingConsentNotice.authorizedUse': '自分にアクセス権のあるアカウント、サブスクリプション、コンテンツのみを使用してください。この機能をプラットフォーム規約、ダウンロード制限、DRM、アカウント保護、ペイウォール、著作権保護の回避に使ってはいけません。',
  'streamingConsentNotice.bodyIntro': 'ECHO Next のストリーミング入口は、検索、アカウント状態、お気に入り、プレイリスト取り込み、再生入口の統合のみを提供します。ECHO は第三者ストリーミングプラットフォームの音声、動画、カバー、歌詞、メタデータの著作権を所有、ホスト、販売、再配布しません。',
