  'streamingConsentNotice.disclaimer': '免責事項：第三者プラットフォームの利用によるアカウント制限、サービス中断、著作権紛争、DMCA 通知、データ損失、地域制限、その他の損失について、ECHO は責任を負いません。',
  'streamingConsentNotice.dmca': 'DMCA は米国著作権法における通知と削除の仕組みです。権利者がコンテンツ、リンク、またはデータ利用が権利を侵害していると考える場合は、該当プラットフォームまたは合法的な経路で通知してください。ユーザーも権利通知やプラットフォームの要請を受けた場合、関連する利用を停止する必要があります。',
  'streamingConsentNotice.inputLabel': '続行するには「{phrase}」と入力してください',
  'streamingConsentNotice.license': 'ECHO のコードとプラグインはプロジェクトのライセンスに従います。クラック、認可回避、権利の偽造、完全性検証の削除、または未許可で有料コンテンツへアクセスする道具としての利用は禁止されています。',
  'streamingConsentNotice.localFirst': 'ECHO は本質的にローカル音楽プレーヤーであり、ストリーミング入口の優先度は最も低いものです。「特定のプラットフォームや音源を追加してほしい」という要求は拒否されます。ストリーミングに問題がある場合は、まずローカル音楽ライブラリを使用してください。',
  'streamingConsentNotice.noBypass': 'ECHO は、いかなるプラットフォームに対しても会員制限の回避、試聴制限の解除、支払い回避、またはプラットフォームや権利者の利益を害する機能を提供しません。曲が 30 秒しか再生されない場合は、プラットフォーム会員、サブスクリプション、地域、アカウント状態を確認してください。',
  'streamingConsentNotice.platformControl': '第三者プラットフォーム、商標、カタログ、API、アカウント、サブスクリプション、Cookie、DRM、地域制限、再生認可は、それぞれのプラットフォームおよび権利者が管理します。ECHO はそれらのプラットフォームを代表せず、プラットフォーム上のコンテンツ利用許可を付与しません。',
